import QtQuick
import Quickshell
import qs.services
import qs.modules.common
import qs.modules.common.widgets
import qs.modules.common.functions

Image {
    id: stateImage
    // Opt in for content images; decorative backgrounds keep their existing behavior.
    property bool showPlaceholder: false
    property string placeholderState: ""
    readonly property bool remoteImage: /^https?:/.test(String(source))
    readonly property string resolvedImageState: placeholderState || (
        status === Image.Loading ? "loading" :
        status === Image.Null ? "no-image" :
        status === Image.Error ? (remoteImage && !Network.ethernet && Network.wifiStatus !== "connected" ? "offline" : "failure") : "")

    Image {
        anchors.centerIn: parent
        width: Math.min(parent.width, parent.height, 48)
        height: width
        visible: stateImage.showPlaceholder && stateImage.resolvedImageState !== ""
        source: Qt.resolvedUrl("../../../assets/image-states/" + (stateImage.resolvedImageState || "no-image") + ".svg")
        fillMode: Image.PreserveAspectFit
        RotationAnimator on rotation {
            from: 0; to: 360; duration: 1400; loops: Animation.Infinite
            running: stateImage.showPlaceholder && stateImage.resolvedImageState === "loading" && stateImage.visible
        }
    }

    asynchronous: true
    retainWhileLoading: true
    visible: opacity > 0
    opacity: (status === Image.Ready || showPlaceholder) ? 1 : 0
    Behavior on opacity {
        animation: Appearance.animation.elementMoveEnter.numberAnimation.createObject(this)
    }

    property list<string> fallbacks: []
    property int currentFallbackIndex: 0

    onStatusChanged: {
        if (status === Image.Error && currentFallbackIndex < fallbacks.length) {
            source = fallbacks[currentFallbackIndex];
            currentFallbackIndex += 1;
        }
    }

    sourceSize: {
        const dpr = (QsWindow.window as QsWindow)?.devicePixelRatio ?? 1;
        return Qt.size(width * dpr, height * dpr);
    }
}

